import * as React from 'react';

/**
 * DSIcon draws an icon from the app's own set, generated by ds-icons (design/icons/icons.json).
 * This package ships no icon data: the app passes its generated module to DSIconProvider once.
 * An unknown name throws, so a missing icon is noticed instead of silently replaced.
 */

export type DSIconShape = readonly [tag: string, attrs: Readonly<Record<string, string>>, filled: boolean];
export interface DSIconData {
  readonly viewBox: string;
  readonly stroke: number;
  readonly filled: boolean;
  readonly shapes: readonly DSIconShape[];
}
export type DSIconSet = Readonly<Record<string, DSIconData>>;
export interface DSIconStyle {
  readonly linecap: string;
  readonly linejoin: string;
}

const IconContext = React.createContext<{ icons: DSIconSet; style: DSIconStyle } | null>(null);

export function DSIconProvider({ icons, style, children }: { icons: DSIconSet; style: DSIconStyle; children?: React.ReactNode }) {
  const value = React.useMemo(() => ({ icons, style }), [icons, style]);
  return <IconContext.Provider value={value}>{children}</IconContext.Provider>;
}

export const DS_ICON_SIZES = { sm: 16, md: 20, lg: 24 } as const;

export interface DSIconProps extends Omit<React.SVGProps<SVGSVGElement>, 'name' | 'viewBox'> {
  name: string;
  size?: keyof typeof DS_ICON_SIZES | number;
  /** Accessible name. Omit for decorative icons next to visible text. */
  label?: string;
}

export function DSIcon({ name, size = 'md', label, ...rest }: DSIconProps) {
  const ctx = React.useContext(IconContext);
  if (!ctx) throw new Error('DSIcon needs a DSIconProvider with the app\'s generated icons (ds-icons build)');
  const icon = ctx.icons[name];
  if (!icon) throw new Error(`DSIcon: "${name}" is not in the app's icon set (design/icons/icons.json)`);
  const px = typeof size === 'number' ? size : DS_ICON_SIZES[size];
  const presentation = icon.filled
    ? { fill: 'currentColor' }
    : { fill: 'none', stroke: 'currentColor', strokeWidth: icon.stroke, strokeLinecap: ctx.style.linecap, strokeLinejoin: ctx.style.linejoin };
  const a11y = label ? { role: 'img', 'aria-label': label } : { 'aria-hidden': true as const };
  return (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox={icon.viewBox} width={px} height={px} {...(presentation as React.SVGProps<SVGSVGElement>)} {...a11y} {...rest}>
      {icon.shapes.map(([tag, attrs, filled], i) =>
        React.createElement(tag, { key: i, ...attrs, fill: filled && !icon.filled ? 'currentColor' : undefined }),
      )}
    </svg>
  );
}
